new:
if (is_mac) {
  # No implementation, allocation, or dependency on the base component. The
  # Crashpad/Framework clients call the one main-executable bridge.
  source_set("aux_browser_descendant_client") {
    public = [
      "process/mac/aux_browser_descendant_bridge.h",
      "process/mac/aux_browser_descendant_client.h",
    ]
    sources = public
  }

  # Only the primary browser image owns the ES stream and ticket registry.
  # mac_app_bundle forwards deps to both its bundle and executable target.
  source_set("aux_browser_descendant_engine") {
    visibility = [
      "//chrome:chrome_app",
      "//chrome:chrome_app_executable",
    ]
    public = [ "process/mac/aux_browser_descendant_engine.h" ]
    sources = [
      "process/mac/aux_browser_descendant_bridge.cc",
      "process/mac/aux_browser_descendant_engine.cc",
      "process/mac/aux_browser_descendant_engine.h",
    ]
    deps = [ ":aux_browser_descendant_client" ]
    configs -= [ "//build/config/compiler:no_exceptions" ]
    configs += [ "//build/config/compiler:exceptions" ]
    cflags_cc = [ "-fblocks" ]
    libs = [
      "EndpointSecurity",
      "bsm",
    ]
  }
}

component("base") {

  "//chrome/common:version_header",
]

ldflags = []
if (enable_aux_browser) {
  defines = [ "AUX_BROWSER_DESCENDANT_CUSTODY" ]
  deps += [ "//base:aux_browser_descendant_engine" ]
  # The Framework resolves only this main-image symbol via RTLD_MAIN_ONLY.
  ldflags += [ "-Wl,-u,_AuxGetBrowserDescendantBridgeV1" ]
}

if (enable_updater) {

if (enable_aux_browser) {
  inputs = [ "app/aux_browser_app.exports" ]
  ldflags += [ "-Wl,-exported_symbols_list," +
               rebase_path("app/aux_browser_app.exports", root_build_dir) ]
} else {
  ldflags += [ "-Wl,-exported_symbols_list," +
               rebase_path("app/app.exports", root_build_dir) ]
}

if (crashpad_is_mac && !crashpad_is_in_fuchsia) {
  if (crashpad_is_in_chromium) {
    # Header-only native bridge; never depend on the full Chromium base
    # component (which already depends on Crashpad) or the observer engine.
    public_deps += [ "//base:aux_browser_descendant_client" ]
  }
  libs = [ "bsm" ]
